practiceProblems.solutionCode:
class Student {
    String name;
    int age;

    Student() {
        name = "Unassigned";
        age = 18;
    }

    void showDetails() {
        System.out.println("Student: " + name + ", Age: " + age);
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student();
        s.showDetails();
    }
}

